from playwright.sync_api import sync_playwright
import os; os.makedirs('test-output', exist_ok=True)
errs=[]
def store(pg, js): return pg.evaluate(f"(async()=>{{const s=await import('./js/state/store.js'); {js} }})()")
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox'])
    pg=b.new_page(viewport={'width':1300,'height':900}); pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('http://localhost:8765/index.html'); pg.evaluate('localStorage.clear(); sessionStorage.clear()'); pg.reload(); pg.wait_for_timeout(600)
    pg.evaluate("location.hash='#space-juniper'"); pg.wait_for_timeout(900)
    m=pg.locator('.module-frame[data-module-type=todo]').first
    print('card filter:', m.locator('.choice-menu__button').inner_text(), '| options visible:', m.locator('.choice-menu__option').count(), '| extras hidden:', m.locator('.todo__form-extras').is_hidden())
    m.locator('.choice-menu__button').click(); pg.wait_for_timeout(100)
    print('   opened:', m.locator('.choice-menu__option').all_inner_texts()); m.locator('.choice-menu__option', has_text='Mine').click(); pg.wait_for_timeout(200)
    print('   now:', m.locator('.choice-menu__button').inner_text(), '| tasks:', m.locator('.todo-item').count())
    t=m.get_by_label('New task', exact=True); t.fill('Buy light bulbs'); pg.wait_for_timeout(100)
    print('   extras after typing:', m.locator('.todo__form-extras').is_visible()); t.press('Enter'); pg.wait_for_timeout(300)
    print('   added via Enter:', store(pg,"return s.getSpace('juniper').modules.find(m=>m.type==='todo').data.tasks.some(t=>t.text==='Buy light bulbs')"))
    m.screenshot(path='test-output/todo-card2.png')
    mid=m.get_attribute('data-module-id'); pg.evaluate(f"location.hash='#module-{mid}'"); pg.wait_for_timeout(800)
    print('page summary:', pg.locator('.todo-page__summary').inner_text().replace('\n',' '))
    print('   show:', pg.locator('.todo-page__toolbar .choice-menu__button').inner_text(), '| selects visible:', pg.locator('.todo-page__toolbar select').count())
    pg.locator('.todo-page__toolbar .choice-menu__button').click(); pg.keyboard.press('ArrowDown'); pg.keyboard.press('Enter'); pg.wait_for_timeout(200)
    print('   keyboard picked:', pg.locator('.todo-page__toolbar .choice-menu__button').inner_text())
    pg.get_by_role('button', name='Sort and filter').click(); pg.wait_for_timeout(100)
    print('   selects after opening:', pg.locator('.todo-page__toolbar select').count())
    pg.locator('.todo-page__add').get_by_label('New task', exact=True).fill('Call landlord'); pg.wait_for_timeout(100); print('   page extras:', pg.locator('.todo-page__add-extras').is_visible())
    pg.locator('.todo-page__add-extras input[type=date]').fill('2026-11-20'); pg.locator('.todo-page__add').get_by_role('button', name='Add', exact=True).click(); pg.wait_for_timeout(300)
    print('   added w/ due:', store(pg,f"return s.getModule('{mid}').data.tasks.find(t=>t.text==='Call landlord')?.due"))
    pg.locator('.todo-stat', has_text='done').click(); pg.wait_for_timeout(200); print('   stat click → show:', pg.locator('.todo-page__toolbar .choice-menu__button').inner_text())
    pg.screenshot(path='test-output/todo-page2.png')
    print('errors', errs); b.close()
